// The only result shape the rest of the application sees.
type Outcome = "complete" | "truncated" | "refused" | "tool_request" | "paused" | "other";

interface ModelResult {
  provider: "anthropic" | "openai" | "google";
  surface: "messages" | "responses" | "generateContent" | "interactions";
  model: string;                 // echoed from configuration, never a code default
  outcome: Outcome;
  text: string;                  // joined text parts only
  toolCalls: { id: string; name: string; args: unknown }[];
  rawStop: string | null;        // the provider value, kept for incident review
  rawUsage: Record<string, unknown>;
}

// Where text, tool requests, and the stop signal live on each native response:
//   Claude Messages          content[] blocks ("text", "tool_use"); stop_reason
//   OpenAI Responses         output[] Items ("message", "function_call", "reasoning", ...); status
//   Gemini generateContent   candidates[].content.parts[]; finishReason
//   Gemini Interactions      steps[] ("model_output", "function_call", ...); status

function claudeOutcome(stop: string | null): Outcome {
  switch (stop) {
    case "end_turn":
    case "stop_sequence": return "complete";
    case "max_tokens":
    case "model_context_window_exceeded": return "truncated";
    case "refusal": return "refused";
    case "tool_use": return "tool_request";
    case "pause_turn": return "paused";      // send the response back to continue
    default: return "other";                 // values added later fail closed
  }
}

function responsesOutcome(r: {
  status: string;
  incomplete_details?: { reason?: string };
  output: { type: string; content?: { type: string }[] }[];
}): Outcome {
  if (r.status === "incomplete") {
    return r.incomplete_details?.reason === "max_output_tokens" ? "truncated" : "other";
  }
  if (r.output.some((i) => i.type === "function_call")) return "tool_request";
  const message = r.output.find((i) => i.type === "message");
  if (message?.content?.some((c) => c.type === "refusal")) return "refused";
  return message ? "complete" : "other";
}

function geminiOutcome(r: { finishReason?: string } | { status?: string }): Outcome {
  if ("status" in r) {                       // Interactions API
    if (r.status === "completed") return "complete";
    if (r.status === "requires_action") return "tool_request";
    return "other";
  }
  // generateContent: only STOP is treated as complete here. Map further
  // finishReason values from the current API reference before trusting them.
  return r.finishReason === "STOP" ? "complete" : "other";
}

// Every guarantee the application depends on, and the request field it rides on.
const guarantees = [
  { name: "tool arguments match the schema", field: "tools[].function.strict" },
  { name: "final answer matches a JSON schema", field: "response_format" },
  { name: "a refusal is machine-detectable", field: "choices[].message.refusal" },
];

// Documented behavior of Claude behind the OpenAI SDK compatibility layer
// (read 2026-09-11, platform.claude.com/docs/en/cli-sdks-libraries/libraries/openai-sdk):
//   tools[].function.strict     -> ignored
//   response_format             -> ignored
//   choices[].message.refusal   -> always empty
// All three guarantees fail on that route. On the native Messages API, use
// output_config.format and strict tool use instead, behind your own adapter.

interface Route {
  provider: "anthropic" | "openai" | "google";
  surface: "messages" | "responses" | "generateContent" | "interactions";
  model: string;        // required -- no default in code
  store: boolean;       // translated per surface; rejected where it cannot be honored
  verifiedOn: string;   // YYYY-MM-DD the id was checked
  verifiedAt: string;   // the models page it was checked against
}

// Example values as read on 2026-09-11 -- load them from configuration:
//   { provider: "anthropic", surface: "messages", model: "claude-sonnet-5",
//     verifiedAt: "https://platform.claude.com/docs/en/models/overview" }
//   { provider: "openai", surface: "responses", model: "gpt-5.6-terra",
//     verifiedAt: "https://developers.openai.com/api/docs/models" }
//   { provider: "google", surface: "generateContent", model: "gemini-3.8-flash",
//     verifiedAt: "https://ai.google.dev/gemini-api/docs/models" }

export function assertRoute(r: Route): Route {
  if (!r.model) throw new Error(`${r.provider}: model id is required; check ${r.verifiedAt}`);
  if (r.surface === "messages" && r.store) {
    throw new Error("Claude Messages keeps no server-side conversation; store:true is not a setting it offers");
  }
  return r;
}
